import Foundation
import XCTest
@testable import IrohaSwift

final class KagemushaWalletSuffixUnloadV1Tests: XCTestCase {
  private let requestID = Data(repeating: 1, count: 32)
  private let amount = KagemushaWalletUInt128V1(low: 1, high: 0)

  func testChargeOriginalsAreInseparableAndBounded() throws {
    XCTAssertNil(try KagemushaWalletSuffixUnloadRequestV1(requestID: requestID, amount: amount).quote)
    for mask in 1...6 {
      XCTAssertThrowsError(try KagemushaWalletSuffixUnloadRequestV1(requestID: requestID, amount: amount,
        quote: mask & 1 != 0 ? Data([1]) : nil, certificates: mask & 2 != 0 ? Data([2]) : nil,
        beneficiary: mask & 4 != 0 ? Data([3]) : nil))
    }
    for sizes in [(0, 1, 1), (1_025, 1, 1), (1, 10_035, 1), (1, 1, 4_097)] {
      XCTAssertThrowsError(try KagemushaWalletSuffixUnloadRequestV1(requestID: requestID, amount: amount,
        quote: Data(repeating: 1, count: sizes.0), certificates: Data(repeating: 1, count: sizes.1),
        beneficiary: Data(repeating: 1, count: sizes.2)))
    }
  }

  func testRequestHasValueSemanticsAndLosslessAmount() throws {
    var identity = requestID, quote = Data([2]), certificates = Data([3]), beneficiary = Data([4])
    let maximum = KagemushaWalletUInt128V1(low: .max, high: .max)
    let request = try KagemushaWalletSuffixUnloadRequestV1(requestID: identity, amount: maximum,
      quote: quote, certificates: certificates, beneficiary: beneficiary)
    identity[0] = 0; quote[0] = 0; certificates[0] = 0; beneficiary[0] = 0
    XCTAssertEqual(request.requestID, requestID); XCTAssertEqual(request.quote, Data([2]))
    XCTAssertEqual(request.certificates, Data([3])); XCTAssertEqual(request.beneficiary, Data([4]))
    XCTAssertEqual(request.amount, maximum)
    for id in [Data(repeating: 1, count: 31), Data(repeating: 0, count: 32), Data(repeating: 1, count: 33)] {
      XCTAssertThrowsError(try KagemushaWalletSuffixUnloadRequestV1(requestID: id, amount: amount))
    }
    XCTAssertThrowsError(try KagemushaWalletSuffixUnloadRequestV1(requestID: requestID, amount: .init(low: 0, high: 0)))
  }

  func testMalformedProjectionCannotBecomeDisplayTerms() throws {
    for bytes in [Data(), Data(repeating: 0, count: 48), Data(repeating: 0, count: 12_289)] {
      XCTAssertThrowsError(try KagemushaWalletSuffixUnloadReviewProjectionV1(bytes))
      XCTAssertThrowsError(try KagemushaWalletSuffixUnloadProgressV1(bytes))
      XCTAssertThrowsError(try KagemushaWalletSuffixUnloadReleasedV1(bytes))
      XCTAssertThrowsError(try KagemushaWalletSuffixUnloadStatusV1(bytes))
    }
  }
  // Canonical fixtures generated by native-vectors.rs from the exact Rust DATA definitions.
  private func fixture(_ name: String) -> Data {
    let hex = fixtures[name]!
    return Data(stride(from: 0, to: hex.count, by: 2).map { at in
      let start = hex.index(hex.startIndex, offsetBy: at)
      return UInt8(hex[start..<hex.index(start, offsetBy: 2)], radix: 16)!
    })
  }
  private let fixtures = [
    "carriage-append": "",
    "carriage-begin": "",
    "carriage-finalize": "",
    "carriage-ordinary": "4e52543000008eef66c2b4be9ed7b2604aec85793350003000000000000000f000acc7e807d03f0200000000000000002002020202020202020202020202020202020202020202020202020202020202020e0600000009010000000000000005",
    "progress-17-of-50": "4e525430000035bc1e23b48598d658d3d844fb9430d60049000000000000007bae5fc72abb1eb3020000000000000000020100020e0020010101010101010101010101010101010101010101010101010101010101010110110000000000000000000000000000001032000000000000000000000000000000",
    "released-u128": "",
    "review-charge-u128": "",
    "review-no-charge-u128": "",
    "status-initializing": "4e52543000001f08d2aade36cb47c6e43694bd101e1e0034000000000000003d510cd9316a3d25020000000000000000020100020f0002000002000001000100010010000000000000000000000000000000001000000000000000000000000000000000",
    "status-verifying-u128": "",
  ]

  func testCanonicalRustProjectionsPreserveCountsAndWideAmounts() throws {
    let progress = try KagemushaWalletSuffixUnloadProgressV1(fixture("progress-17-of-50"))
    XCTAssertEqual(progress.completedSteps, .init(low: 17, high: 0))
    XCTAssertEqual(progress.totalSteps, .init(low: 50, high: 0))
    let status = try KagemushaWalletSuffixUnloadStatusV1(fixture("status-verifying-u128"))
    XCTAssertEqual(status.currentSequence, .init(low: 99, high: 1))
    XCTAssertEqual(status.foldedSequence, .init(low: 49, high: 1))
    XCTAssertEqual(status.requestID, requestID)
    let empty = try KagemushaWalletSuffixUnloadStatusV1(fixture("status-initializing"))
    XCTAssertNil(empty.requestID); XCTAssertNil(empty.currentSequence); XCTAssertNil(empty.foldedSequence)
    let released = try KagemushaWalletSuffixUnloadReleasedV1(fixture("released-u128"))
    XCTAssertEqual(released.amount, .init(low: 123, high: 1))
    XCTAssertEqual(released.instructionCount, .init(low: 9, high: 0))
    for (name, fee) in [("review-no-charge-u128", UInt64(0)), ("review-charge-u128", UInt64(17))] {
      let review = try KagemushaWalletSuffixUnloadReviewProjectionV1(fixture(name))
      XCTAssertEqual(review.amount, .init(low: 123, high: 1)); XCTAssertEqual(review.charge, .init(low: fee, high: 0))
      XCTAssertEqual(review.netDestinationAmount, .init(low: 123 - fee, high: 1))
      XCTAssertEqual(review.stepCount, released.stepCount); XCTAssertEqual(review.chunkCount, released.chunkCount)
      XCTAssertEqual(review.instructionCount, released.instructionCount)
    }
  }

  func testCanonicalFramesRejectTruncationTrailingBytesWrongSchemaAndChangedPayload() throws {
    let original = fixture("review-no-charge-u128")
    var schema = original; schema[10] ^= 1
    var payload = original; payload[payload.count - 1] ^= 1
    for bad in [Data(original.dropLast()), original + Data([0]), schema, payload, fixture("released-u128")] {
      XCTAssertThrowsError(try KagemushaWalletSuffixUnloadReviewProjectionV1(bad))
    }
  }

  func testReviewIsOwnerBoundSingleUseAndOnlyExactRetainedTokenRestoresIt() throws {
    let owner = NSObject()
    let reply = try KagemushaWalletSuffixUnloadReplyV1(status: 73, sequenceLow: 42, bytes: fixture("review-no-charge-u128"))
    guard case .ready(let review) = try reply.decision(origin: owner, requestID: requestID) else { return XCTFail("expected review") }
    XCTAssertThrowsError(try review.consume(origin: NSObject()))
    let token = try review.consume(origin: owner); XCTAssertEqual(token, 42)
    XCTAssertThrowsError(try review.consume(origin: owner))
    XCTAssertThrowsError(try KagemushaWalletSuffixUnloadReplyV1(status: 65, sequenceLow: 43, detail: 6)
      .execution(origin: owner, review: review, consumed: token))
    _ = try KagemushaWalletSuffixUnloadReplyV1(status: 65, sequenceLow: 42, detail: 6)
      .execution(origin: owner, review: review, consumed: token)
    XCTAssertEqual(try review.consume(origin: owner), 42)
    guard case .released(let summary) = try KagemushaWalletSuffixUnloadReplyV1(status: 74, bytes: fixture("released-u128"))
      .execution(origin: owner, review: review, consumed: token) else { return XCTFail("expected released") }
    XCTAssertEqual(summary.amount, review.projection.amount)
    XCTAssertThrowsError(try review.consume(origin: owner))
    XCTAssertThrowsError(try reply.decision(origin: owner, requestID: Data(repeating: 2, count: 32)))
  }

  func testStageConfirmationAndPayoutKeepDistinctTagsAndCertifiedIdentity() throws {
    for kind: Int32 in [69, 70, 76] {
      let reply = try KagemushaWalletSuffixUnloadReplyV1(status: kind, sequenceLow: .max, bytes: Data(repeating: 5, count: 32))
      XCTAssertEqual(reply.status, kind)
      for height: UInt64 in [0, 1] {
        XCTAssertThrowsError(try KagemushaWalletSuffixUnloadReplyV1(status: kind, sequenceLow: height, bytes: Data(repeating: 5, count: 32)))
      }
      XCTAssertThrowsError(try KagemushaWalletSuffixUnloadReplyV1(status: kind, sequenceLow: 2, bytes: Data(repeating: 0, count: 32)))
    }
    XCTAssertThrowsError(try KagemushaWalletSuffixUnloadReplyV1(status: 65, sequenceLow: 1, detail: 2))
    XCTAssertNoThrow(try KagemushaWalletSuffixUnloadReplyV1(status: 78))
    XCTAssertThrowsError(try KagemushaWalletSuffixUnloadReplyV1(status: 75))
  }

  func testSuffixCarriageAcceptsOnlyCanonicalSuffixActionShapes() throws {
    for name in ["carriage-begin", "carriage-append", "carriage-finalize"] {
      let frame = fixture(name)
      XCTAssertEqual(try KagemushaWalletSuffixUnloadV1.instructionOriginal(frame), frame)
      XCTAssertThrowsError(try KagemushaWalletSuffixUnloadV1.instructionOriginal(frame + Data([0])))
    }
    XCTAssertThrowsError(try KagemushaWalletSuffixUnloadV1.instructionOriginal(fixture("carriage-ordinary")))
    XCTAssertThrowsError(try KagemushaWalletSuffixUnloadV1.instructionOriginal(fixture("released-u128")))
    XCTAssertThrowsError(try KagemushaWalletSuffixUnloadV1.instructionOriginal(Data(repeating: 0, count: KagemushaWalletSuffixUnloadV1.instructionMaximumBytes + 1)))
  }

}
